import {e,actionLink,title,state,safeExternal} from '../lib.js';
import {sectionHeader} from '../components/layout.js';
const realScreens=['/media-app-settings.png','/media/5888658608638071244_121.jpg','/media/5888658608638071251_121.jpg','/media/5888658608638071252_121.jpg'];
export function home(){title('المنظومة','OnStar لإدارة الشبكات من هاتفك وOnStar Cloud للوصول عن بُعد');return `
<section class="hero-shell"><div class="shell hero-head"><div class="hero-index"><span>NETWORK MANAGEMENT / REIMAGINED</span><span>01 — 2026</span></div><div class="hero-title"><h1>اتصالٌ أقرب.<br/><em>تحكّمٌ أبعد.</em></h1><div class="hero-side"><div class="fine-line"></div><p>من إدارة صفحة الدخول والأدوات على هاتفك، إلى الوصول لأجهزة شبكتك من أي مكان. منتجان، منظومة واحدة.</p><div class="hero-actions">${actionLink('/app','اكتشف التطبيق','light')}${actionLink('/cloud','استكشف Cloud','outline-light')}</div></div></div></div>
<div class="hero-scene" aria-label="رسم توضيحي لاتصال الهاتف بالشبكة والخدمة السحابية"><div class="scene-grid"></div><div class="scene-arc arc-1"></div><div class="scene-arc arc-2"></div><div class="scene-arc arc-3"></div><div class="scene-core"><span class="mini-label">THE NETWORK, IN YOUR HANDS</span><strong>ON<span>STAR</span></strong><div class="core-ring"></div></div><div class="scene-node scene-node-app"><div class="node-led"></div><span>ONSTAR APP</span><b>الإدارة المحلية</b></div><div class="scene-node scene-node-cloud"><div class="node-led"></div><span>ONSTAR CLOUD</span><b>الوصول عن بُعد</b></div><span class="scene-caption">A CONNECTED NETWORK ECOSYSTEM <span>◉</span> VISUAL CONCEPT</span></div></section>
<section class="intro-statement section-light"><div class="shell"><div class="split-meta"><span class="eyebrow">01 / THE ECOSYSTEM</span><span>منظومة OnStar</span></div><div class="statement-wrap"><h2>ليس مجرد تطبيق.<br/><em>ولا مجرد خدمة سحابية.</em></h2><p>تجربتان صُمِّمتا لغرضين مختلفين. اختر ما يناسب عملك، من دون تعقيد أو تشتيت.</p></div><div class="product-switch" id="product-switch" role="group" aria-label="اختر المنتج"><button type="button" class="product-switch-button active" data-product="app" aria-pressed="true"><span>01</span> تطبيق OnStar <span>↗</span></button><button type="button" class="product-switch-button" data-product="cloud" aria-pressed="false"><span>02</span> OnStar Cloud <span>↗</span></button></div><div id="product-stage">${productStage('app')}</div></div></section>
<section class="feature-editorial section-dark"><div class="shell"><div class="split-meta"><span class="eyebrow">02 / BUILT FOR CONTROL</span><span>تفاصيل تصنع الفرق</span></div><div class="editorial-grid"><div class="editorial-copy">${sectionHeader('ONSTAR APP','كل أداة<br/><em>في متناولك.</em>','إدارة HotSpot والسرعات والتحديثات وأدوات MikroTik من واجهة الهاتف.')}${actionLink('/tools','استعراض جميع الأدوات','outline-light')}<div class="editorial-kpis"><div><strong>128</strong><span>أداة موثقة</span></div><div><strong>35</strong><span>شرح فيديو</span></div></div></div><div class="editorial-gallery"><img loading="lazy" src="${realScreens[1]}" alt="لقطة أصلية من واجهة OnStar"/><img loading="lazy" src="${realScreens[2]}" alt="لقطة ثانية أصلية من تطبيق OnStar"/><div class="gallery-caption">ACTUAL APP INTERFACES <span>01 / 02</span></div></div></div></div></section>
<section class="cloud-canvas section-light"><div class="shell"><div class="split-meta"><span class="eyebrow">03 / BEYOND YOUR NETWORK</span><span>الوصول السحابي</span></div><div class="cloud-statement"><div><span class="micro-mark">ONSTAR CLOUD / ACCESS</span><h2>أجهزتك هناك.<br/><em>أنت تديرها من هنا.</em></h2><p>انقل إدارة أجهزتك من حدود الشبكة المحلية إلى واجهة وصول منظّمة، بحسب حالة الاشتراك وصلاحيات حسابك.</p>${actionLink('/cloud','تعرف على OnStar Cloud')}</div><div class="cloud-map">${cloudDiagram()}</div></div></div></section>
<section class="academy-band section-dark"><div class="shell academy-band-layout"><div><span class="eyebrow">04 / KNOWLEDGE CENTER</span><h2>المعرفة جزءٌ<br/><em>من المنظومة.</em></h2></div><div><p>128 دليل أداة، و36 شرحًا للوحة الأجهزة، و35 فيديو من المكتبة الأصلية. ابحث، تعلّم، وارجع إلى الخطوة التي تحتاجها.</p>${actionLink('/knowledge','زيارة مركز المعرفة','light')}</div></div></section>
<section class="bottom-cta section-light"><div class="shell"><span class="eyebrow">MAKE YOUR NETWORK WORK SMARTER</span><h2>جاهز للمرحلة<br/><em>التالية من الإدارة؟</em></h2><div class="cta-buttons">${actionLink('/app','تطبيق OnStar')}${actionLink('/register','إنشاء حساب Cloud','dark-outline')}</div></div></section>`}
export function productStage(which){if(which==='cloud')return `<div class="stage-area stage-cloud"><div class="stage-image">${cloudDiagram()}</div><div class="stage-copy"><span class="eyebrow">ONSTAR CLOUD / 02</span><h3>الوصول عندما تحتاجه.</h3><p>إدارة أجهزة الشبكة خارج نطاقها المحلي، ومتابعة الاشتراك والفواتير وعناوين الوصول من لوحة خاصة.</p><ul><li>لوحة مشترك واضحة</li><li>الوصول لأجهزة الشبكة المدعومة</li><li>متابعة حالة الخدمة</li></ul>${actionLink('/cloud','استكشاف Cloud','dark-outline')}</div></div>`;return `<div class="stage-area"><div class="stage-image device-stage"><div class="phone-frame"><div class="phone-notch"></div><img loading="lazy" src="/media-app-settings.png" alt="واجهة حقيقية من تطبيق OnStar"/></div><span class="device-caption">ONSTAR / ANDROID EXPERIENCE</span></div><div class="stage-copy"><span class="eyebrow">ONSTAR APP / 01</span><h3>أدوات شبكتك، في جيبك.</h3><p>تطبيق Android لإدارة صفحات HotSpot وإعدادات الشبكة، يعرض وظائف موثقة يمكن الوصول إليها مباشرة من الهاتف.</p><ul><li>صفحات الدخول والتصاميم</li><li>السرعات والتحديثات</li><li>أدوات MikroTik والحماية</li></ul>${actionLink('/app','استكشاف التطبيق','dark-outline')}</div></div>`}
export function cloudDiagram(){return `<div class="diagram" aria-label="رسم توضيحي غير مباشر لحركة الاتصال، وليس حالة أجهزة حقيقية"><div class="diagram-orbit o1"></div><div class="diagram-orbit o2"></div><div class="diagram-line l1"></div><div class="diagram-line l2"></div><div class="diagram-hub"><span>◈</span><b>ONSTAR</b><small>CLOUD</small></div><div class="diagram-point d1">جهاز المستخدم<small>CONTROL PANEL</small></div><div class="diagram-point d2">MikroTik<small>NETWORK EDGE</small></div><div class="diagram-point d3">أجهزة الشبكة<small>MANAGED DEVICES</small></div><span class="diagram-label">ILLUSTRATIVE CONNECTION FLOW</span></div>`}
export function appProduct(){title('تطبيق OnStar','أدوات OnStar لإدارة صفحات الدخول وإعدادات MikroTik');const cats=state.content.toolCategories;return `
<section class="product-hero section-dark"><div class="shell product-hero-grid"><div class="product-head"><span class="eyebrow">ONSTAR / THE ANDROID APP</span><h1>قوة إدارة الشبكة.<br/><em>في راحة يدك.</em></h1><p>مساحة عمل يومية لمدير الشبكة: تجهيز صفحات HotSpot، ضبط السرعات والتحديثات، والتحكم بأدوات MikroTik الموثقة.</p><div class="hero-actions">${actionLink('/tools','اكتشف الأدوات','light')}${actionLink('/videos','شاهد الشروحات','outline-light')}</div><div class="product-facts"><div><b>128</b><span>أداة موثقة</span></div><div><b>11</b><span>تصنيفًا رئيسيًا</span></div><div><b>35</b><span>فيديو تعليميًا</span></div></div></div><div class="product-visual"><div class="phone-frame prominent"><div class="phone-notch"></div><img src="/media-app-settings.png" alt="لقطة أصلية لواجهة إعدادات OnStar"/></div><div class="floating-note"><span class="signal-dot"></span>ACTUAL APPLICATION SCREEN</div></div></div></section>
<section class="section-light product-tracks"><div class="shell"><div class="split-meta"><span class="eyebrow">FEATURE LANDSCAPE</span><span>ماذا يمكنك إنجازه؟</span></div>${sectionHeader('A COMPLETE TOOLSET','من صفحة الدخول<br/><em>إلى إدارة الشبكة.</em>','مزايا التطبيق الفعلية موزعة ضمن أقسام يسهل الرجوع إليها.')}
<div class="tracks-list">${cats.map((c,i)=>`<a href="/tools?category=${encodeURIComponent(c.id)}" data-link class="track"><span class="track-number">${String(i+1).padStart(2,'0')}</span><div><h3>${e(c.title)}</h3><p>${e(c.description||'استعراض الأدوات المرتبطة بهذا القسم')}</p></div><span class="track-count">${state.content.tools.filter(t=>t.category===c.id).length} أداة</span><span class="track-arrow">↗</span></a>`).join('')}</div></div></section>
<section class="section-dark screenshots-section"><div class="shell"><div class="split-meta"><span class="eyebrow">REAL INTERFACES / NO MOCKUPS</span><span>صور من المشروع الأصلي</span></div>${sectionHeader('APP IN ACTION','واجهة مألوفة للمهندس.<br/><em>أوسع في الإمكانات.</em>')}<div class="screen-wall">${realScreens.map((src,i)=>`<figure><img loading="lazy" src="${src}" alt="صورة أصلية رقم ${i+1} من واجهات OnStar"/><figcaption>OnStar / ${String(i+1).padStart(2,'0')}</figcaption></figure>`).join('')}</div></div></section>
<section class="bottom-cta section-light"><div class="shell"><span class="eyebrow">ONSTAR ACADEMY</span><h2>اكتشف وظيفة<br/><em>كل أداة بالتفصيل.</em></h2><div class="cta-buttons">${actionLink('/tools','دليل الأدوات')}${actionLink('/videos','مكتبة الفيديو','dark-outline')}</div></div></section>`}
const howCloud=[['01','إنشاء الحساب','أدخل بياناتك الأساسية واسم الشبكة.'],['02','تأكيد البريد','أدخل رمز التحقق المرسل إلى بريدك الإلكتروني.'],['03','الباقة والتحقق','راجع الباقات المتاحة وأكمل التحقق من MikroTik.'],['04','طلب التجربة أو الاشتراك','أرسل طلب التجربة المؤهَّل أو طلب الباقة وإثبات الدفع.'],['05','مراجعة الإدارة','انتظر قبول الطلب أو اعتماد الدفع؛ الإرسال ليس تفعيلًا.'],['06','إعداد الاتصال','بعد تجهيز الخدمة استخدم كود إعداد الاتصال المتاح في حسابك.'],['07','الوصول إلى الأجهزة','افتح عناوين الوصول واللوحة المتاحة ضمن صلاحياتك.']];
export function cloudProduct(){title('OnStar Cloud','إدارة الوصول إلى أجهزة الشبكة عن بُعد');const types=['MikroTik','TP-Link','Ubiquiti / NanoStation','OpenWrt','Access Points','أجهزة البث المدعومة'];return `<section class="product-hero cloud-product section-dark"><div class="shell"><span class="eyebrow">ONSTAR CLOUD / REMOTE NETWORK ACCESS</span><div class="cloud-hero-grid"><div><h1>تتغير الأماكن.<br/><em>ويبقى الوصول.</em></h1><p>خدمة اشتراك للوصول المنظّم إلى أجهزة الشبكة وإدارتها عن بُعد، عبر العناوين والخدمات التي يتيحها نظامك.</p><div class="hero-actions">${actionLink('/register','ابدأ حسابك','light')}${actionLink('/customer-login','دخول المشترك','outline-light')}</div><span class="micro-note">تفعيل الخدمة حسب الاشتراك وموافقة الإدارة. الرسم توضيحي وليس بيانات مباشرة.</span></div>${cloudDiagram()}</div></div></section>
<section class="cloud-features section-light"><div class="shell"><div class="split-meta"><span class="eyebrow">WHY ONSTAR CLOUD</span><span>المرونة، عندما تحتاجها</span></div><div class="cloud-features-grid"><div class="cloud-feature-lead"><h2>الوصول لا ينبغي<br/><em>أن يتوقف عند حدود المكان.</em></h2></div><div class="feature-small"><span>01 / ACCESS</span><h3>أجهزتك في متناولك</h3><p>استخدم منافذ الوصول وروابط الإدارة المخصصة لك عندما تكون الخدمة متاحة.</p></div><div class="feature-small"><span>02 / ORGANIZATION</span><h3>إدارة أجهزة أوضح</h3><p>انتقل إلى لوحة الأجهزة المخصصة لشبكتك بحسب صلاحيات حسابك.</p></div><div class="feature-small"><span>03 / SUBSCRIPTION</span><h3>كل ما يتعلق باشتراكك</h3><p>شاهد حالات الخدمة والباقات والطلبات والفواتير من حساب واحد.</p></div></div></div></section>
<section class="cloud-process section-dark"><div class="shell"><div class="split-meta"><span class="eyebrow">GET STARTED / 07 STEPS</span><span>الرحلة إلى أول اتصال</span></div>${sectionHeader('THE PROCESS','من إنشاء الحساب<br/><em>إلى أجهزتك.</em>','قد تختلف الخطوات التي تظهر بحسب حسابك وحالة الخدمة، والسيرفر هو المرجع النهائي.')}
<div class="process-line">${howCloud.map(([n,t,d])=>`<div class="process-step"><span>${n}</span><div><h3>${e(t)}</h3><p>${e(d)}</p></div></div>`).join('')}</div>${actionLink('/register','إنشاء حساب مشترك','light')}</div></section>
<section class="hardware-section section-light"><div class="shell"><div class="split-meta"><span class="eyebrow">SUPPORTED ENVIRONMENT</span><span>التوافق حسب تجهيز شبكتك</span></div>${sectionHeader('NETWORK DEVICES','أجهزة مختلفة.<br/><em>إدارة من نقطة واحدة.</em>','تظهر لك خدمات الأجهزة المتاحة فقط عند دعمها وتهيئتها في حسابك.')}
<div class="hardware-line">${types.map((t,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><h3>${e(t)}</h3><span>↗</span></div>`).join('')}</div></div></section>
<section class="bottom-cta section-dark"><div class="shell"><span class="eyebrow">ONSTAR CLOUD / MEMBERSHIP</span><h2>ابدأ إدارة شبكتك<br/><em>من أي مكان.</em></h2><div class="cta-buttons">${actionLink('/register','إنشاء حساب Cloud','light')}${actionLink('/knowledge','تعرف على الخدمة','outline-light')}</div></div></section>`}
export function services(){title('خدمات الفريق');const services=state.content.content.teamServices;return `<section class="page-title dark"><div class="shell"><span class="eyebrow">ONSTAR / PROFESSIONAL SERVICES</span><h1>خبرة عملية.<br/><em>حلول مناسبة لشبكتك.</em></h1><p>خدمات تطوير وإعداد فنية مستقلة عن اشتراك التطبيق وخدمة OnStar Cloud.</p></div></section><section class="section-light pad-y"><div class="shell service-cards">${services.map((s,i)=>`<article><span>${String(i+1).padStart(2,'0')} / SERVICES</span><h2>${e(s.title)}</h2><p>${e(s.text)}</p></article>`).join('')}</div></section><section class="bottom-cta section-dark"><div class="shell"><span class="eyebrow">WORK WITH US</span><h2>لنتحدث عن<br/><em>احتياج شبكتك.</em></h2>${actionLink('/contact','التواصل مع الفريق','light')}</div></section>`}
export function contact(){title('تواصل معنا');const w=state.content.whatsapp;const link=(url,t,desc)=>{const u=safeExternal(url);return u?`<a href="${e(u)}" target="_blank" rel="noopener noreferrer" class="contact-line"><div><span class="eyebrow">SUPPORT / ONSTAR</span><h2>${e(t)}</h2><p>${e(desc)}</p></div><span>↗</span></a>`:''};return `<section class="page-title dark"><div class="shell"><span class="eyebrow">LET'S CONNECT</span><h1>خلف كل شبكة،<br/><em>فريق يساعدك.</em></h1><p>للدعم الفني، والاستفسارات، ومتابعة مجتمع المستخدمين.</p></div></section><section class="section-light pad-y"><div class="shell">${link(w.developer,'تواصل مع المطور','استفسارات فنية وخدمات الفريق.')}${link(w.group,'مجتمع OnStar','التحديثات والشروحات والتواصل مع المستخدمين.')}</div></section>`}
export function faq(){title('الأسئلة الشائعة');const f=state.content.content.faqs;return `<section class="page-title dark"><div class="shell"><span class="eyebrow">HELP / FREQUENTLY ASKED</span><h1>إجابات واضحة.<br/><em>خطوة أقرب للحل.</em></h1><p>الأسئلة الشائعة كما وردت ضمن المحتوى الأصلي للمشروع.</p></div></section><section class="section-light pad-y"><div class="shell faq-list">${f.map((x,i)=>`<details ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span>${e(x.q||x.question||x.title)}<b>+</b></summary><p>${e(x.a||x.answer||x.text)}</p></details>`).join('')}</div></section>`}
